require_once __DIR__.'/includes/email.php';email_require('providers');$pageTitle='سرویس‌دهندگان ایمیل';
function email_oauth_config(?array $existing,array $input): ?string{$config=$existing?:[];foreach(['client_id','authorization_url','token_url','redirect_uri'] as $key){$value=trim((string)($input['oauth_'.$key]??''));if($value==='')unset($config[$key]);else$config[$key]=$value;}foreach(['authorization_url','token_url','redirect_uri'] as $key){if(isset($config[$key])&&!filter_var($config[$key],FILTER_VALIDATE_URL))throw new InvalidArgumentException('نشانی‌های OAuth باید URL معتبر باشند.');}$secret=trim((string)($input['oauth_client_secret']??''));if($secret!=='')$config['client_secret_encrypted']=EmailCrypto::encrypt($secret);elseif(!empty($config['client_secret'])&&empty($config['client_secret_encrypted']))$config['client_secret_encrypted']=EmailCrypto::encrypt((string)$config['client_secret']);unset($config['client_secret']);$scopes=preg_split('/[\s,]+/u',trim((string)($input['oauth_scopes']??'')),-1,PREG_SPLIT_NO_EMPTY)?:[];if($scopes)$config['scopes']=array_values(array_unique($scopes));else unset($config['scopes']);return $config?json_encode($config,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null;}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/email-providers.php');}try{$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$code=strtolower(trim((string)($_POST['code']??'')));if($name===''||!preg_match('/^[a-z0-9_-]{2,100}$/',$code))throw new InvalidArgumentException('نام و کد معتبر سرویس‌دهنده الزامی است.');$existing=$id?Database::fetch('SELECT oauth_config_json FROM email_providers WHERE id=?',[$id]):null;$oauthExisting=json_decode((string)($existing['oauth_config_json']??''),true);$oauth=email_oauth_config(is_array($oauthExisting)?$oauthExisting:[],$_POST);$data=[$name,$code,in_array($_POST['provider_type']??'',['gmail','yahoo','website','custom'],true)?$_POST['provider_type']:'custom',trim((string)($_POST['imap_host']??'')),max(1,min(65535,(int)($_POST['imap_port']??993))),in_array($_POST['imap_encryption']??'',['ssl','tls','none'],true)?$_POST['imap_encryption']:'ssl',trim((string)($_POST['smtp_host']??'')),max(1,min(65535,(int)($_POST['smtp_port']??587))),in_array($_POST['smtp_encryption']??'',['ssl','tls','none'],true)?$_POST['smtp_encryption']:'tls',in_array($_POST['auth_type']??'',['password','app_password','oauth2'],true)?$_POST['auth_type']:'password',$oauth,isset($_POST['active'])?1:0];if($id)Database::execute('UPDATE email_providers SET name=?,code=?,provider_type=?,imap_host=?,imap_port=?,imap_encryption=?,smtp_host=?,smtp_port=?,smtp_encryption=?,auth_type=?,oauth_config_json=?,active=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else Database::execute('INSERT INTO email_providers(name,code,provider_type,imap_host,imap_port,imap_encryption,smtp_host,smtp_port,smtp_encryption,auth_type,oauth_config_json,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())',$data);EmailHubModule::log(null,null,'provider_saved','سرویس‌دهنده ایمیل ذخیره شد.',null,['provider_id'=>$id?:Database::lastInsertId()]);flash('سرویس‌دهنده ایمیل ذخیره شد.');}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){flash(email_safe_error($e,'ذخیره سرویس‌دهنده انجام نشد.'),'danger');}redirect('/admin/email-providers.php');}
$edit=isset($_GET['edit'])?Database::fetch('SELECT * FROM email_providers WHERE id=?',[(int)$_GET['edit']]):null;$editOauth=json_decode((string)($edit['oauth_config_json']??''),true);if(!is_array($editOauth))$editOauth=[];$providers=Database::fetchAll('SELECT p.*,(SELECT COUNT(*) FROM email_accounts a WHERE a.provider_id=p.id) account_count FROM email_providers p ORDER BY p.active DESC,p.name');require __DIR__.'/../views/partials/admin-header.php';?>
