ass="form-field"><span>نوع احراز هویت</span><select name="auth_type"><?php foreach(['password'=>'رمز عبور','app_password'=>'App Password','oauth2'=>'OAuth2'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['auth_type']??'password')===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></label></div><details class="email-advanced" <?=($edit['auth_type']??'')==='oauth2'?'open':''?>><summary>تنظیمات OAuth2</summary><div class="grid grid-2"><label class="form-field"><span>Client ID</span><input name="oauth_client_id" dir="ltr" value="<?=e($editOauth['client_id']??'')?>"></label><label class="form-field"><span>Client Secret</span><input type="password" name="oauth_client_secret" dir="ltr" autocomplete="new-password" placeholder="<?=isset($editOauth['client_secret_encrypted'])||isset($editOauth['client_secret'])?'برای حفظ مقدار فعلی خالی بگذارید':'فقط هنگام نیاز وارد کنید'?>"></label><label class="form-field"><span>Authorization URL</span><input type="url" name="oauth_authorization_url" dir="ltr" value="<?=e($editOauth['authorization_url']??'')?>"></label><label class="form-field"><span>Token URL</span><input type="url" name="oauth_token_url" dir="ltr" value="<?=e($editOauth['token_url']??'')?>"></label><label class="form-field"><span>Redirect URI</span><input type="url" name="oauth_redirect_uri" dir="ltr" value="<?=e($editOauth['redirect_uri']??'')?>"></label><label class="form-field"><span>Scopeها</span><input name="oauth_scopes" dir="ltr" value="<?=e(implode(', ',is_array($editOauth['scopes']??null)?$editOauth['scopes']:[]))?>" placeholder="openid, email, profile"></label></div><small>ساختار داخلی به‌صورت رمزنگاری‌شده ذخیره می‌شود؛ Client Secret ذخیره‌شده دوباره نمایش داده نمی‌شود.</small></details><label class="checkbox-item"><input type="checkbox" name="active" <?=!isset($edit['active'])||(int)$edit['active']?'checked':''?>> فعال</label><div class="form-actions"><button class="btn btn-primary">ذخیره سرویس‌دهنده</button><?php if($edit):?><a class="btn" href="/admin/email-providers.php">انصراف</a><?php endif?></div></form></section>
<section class="card"><div class="table-wrap"><table><thead><tr><th>سرویس‌دهنده</th><th>IMAP</th><th>SMTP</th><th>احراز هویت</th><th>حساب‌ها</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($providers as $p):?><tr><td><strong><?=e($p['name'])?></strong><small><?=e($p['code'])?></small></td><td dir="ltr"><?=e($p['imap_host'].':'.$p['imap_port'].' / '.$p['imap_encryption'])?></td><td dir="ltr"><?=e($p['smtp_host'].':'.$p['smtp_port'].' / '.$p['smtp_encryption'])?></td><td><?=e(['password'=>'رمز عبور','app_password'=>'App Password','oauth2'=>'OAuth2'][$p['auth_type']]??'')?></td><td><?=e((string)$p['account_count'])?></td><td><?=$p['active']?'فعال':'غیرفعال'?></td><td><a class="btn btn-small" href="?edit=<?=$p['id']?>">ویرایش</a></td></tr><?php endforeach?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
